const char *tzPosix(const char *name) {
  if (!name) return nullptr;
  char cur[TZ_NAME_MAX + 1];
  size_t pos = 0;
  for (uint16_t i = 0; i < TZ_NAMES_COUNT; i++) {
    uint8_t kept = NAMES[pos], len = NAMES[pos + 1];
    memcpy(cur + kept, NAMES + pos + 2, len);
    cur[kept + len] = '\0';
    uint8_t zone = NAMES[pos + 2 + len];
    pos += 3 + len;
    int order = strcmp(cur, name);
    if (order > 0) break;   // sorted: it is not further on
    if (order < 0) continue;
    const char *p = POSIX;
    for (uint8_t z = 0; z < zone; z++) p += strlen(p) + 1;
    return p;
  }
  return nullptr;
}
